def choose_move(observation):
    def clamp_step(v):
        return -1 if v < 0 else (1 if v > 0 else 0)

    def get(obj, key, default=None):
        try:
            return obj.get(key, default)
        except Exception:
            return default

    def as_pos(x):
        if isinstance(x, (list, tuple)) and len(x) >= 2:
            return x[0], x[1]
        return None

    def norm_pos_list(v):
        if v is None:
            return []
        out = []
        if isinstance(v, (list, tuple)):
            for item in v:
                p = as_pos(item)
                if p is not None:
                    out.append(p)
        return out

    def nearest(src, pts):
        if src is None or not pts:
            return None
        sx, sy = src
        best = None
        best_d = None
        for px, py in pts:
            d = abs(px - sx) + abs(py - sy)
            if best_d is None or d < best_d:
                best_d = d
                best = (px, py)
        return best

    def score_move(src, mv, targets, threats, bounds=None):
        if src is None:
            return 0
        nx, ny = src[0] + mv[0], src[1] + mv[1]
        s = 0
        if targets:
            t = nearest((nx, ny), targets)
            if t is not None:
                s -= abs(t[0] - nx) + abs(t[1] - ny)
        if threats:
            for tx, ty in threats:
                d = abs(tx - nx) + abs(ty - ny)
                if d == 0:
                    s -= 50
                elif d == 1:
                    s -= 10
                elif d == 2:
                    s -= 3
        if bounds is not None:
            try:
                w = bounds[0]
                h = bounds[1]
                if nx < 0 or ny < 0 or nx >= w or ny >= h:
                    s -= 20
            except Exception:
                pass
        return s

    # Extract common fields defensively
    me = as_pos(get(observation, "agent_pos", None))
    if me is None:
        me = as_pos(get(observation, "self_pos", None))
    if me is None:
        me = as_pos(get(observation, "position", None))
    if me is None:
        me = as_pos(get(observation, "pos", None))

    if me is None:
        return [0, 0]

    resources = norm_pos_list(get(observation, "resources", None))
    if not resources:
        resources = norm_pos_list(get(observation, "resource_positions", None))
    if not resources:
        resources = norm_pos_list(get(observation, "food", None))
    if not resources:
        resources = norm_pos_list(get(observation, "collectibles", None))

    enemies = norm_pos_list(get(observation, "enemies", None))
    if not enemies:
        enemies = norm_pos_list(get(observation, "opponents", None))
    if not enemies:
        enemies = norm_pos_list(get(observation, "enemy_positions", None))

    bases = norm_pos_list(get(observation, "bases", None))
    if not bases:
        bases = norm_pos_list(get(observation, "territories", None))
    if not bases:
        bases = norm_pos_list(get(observation, "capture_points", None))

    hazards = norm_pos_list(get(observation, "hazards", None))
    if not hazards:
        hazards = norm_pos_list(get(observation, "obstacles", None))
    if not hazards:
        hazards = norm_pos_list(get(observation, "walls", None))

    bounds = get(observation, "board_size", None)
    if bounds is None:
        bounds = get(observation, "grid_size", None)

    # Prefer resources if present.
    target = None
    if resources:
        target = nearest(me, resources)
    elif bases:
        target = nearest(me, bases)
    elif enemies:
        # In pursuit / territory, move toward nearest opponent unless threatening.
        target = nearest(me, enemies)

    moves = [(0, 0), (1, 0), (-1, 0), (0, 1), (0, -1)]
    best_mv = (0, 0)
    best_sc = None

    # If enemies exist, add simple evasive behavior when too close.
    avoid_mode = False
    if enemies:
        nearest_enemy = nearest(me, enemies)
        if nearest_enemy is not None:
            ed = abs(nearest_enemy[0] - me[0]) + abs(nearest_enemy[1] - me[1])
            if ed <= 2:
                avoid_mode = True

    for mv in moves:
        sc = 0
        # basic target seeking
        if target is not None and not avoid_mode:
            nx = me[0] + mv[0]
            ny = me[1] + mv[1]
            sc -= abs(target[0] - nx) + abs(target[1] - ny)
        elif avoid_mode and enemies:
            nx = me[0] + mv[0]
            ny = me[1] + mv[1]
            # maximize distance from nearest enemy
            ne = nearest((nx, ny), enemies)
            if ne is not None:
                sc += abs(ne[0] - nx) + abs(ne[1] - ny)

        sc += score_move(me, mv, resources if resources else bases, hazards, bounds)
        if enemies and not avoid_mode:
            # slight penalty for proximity to enemy
            for ex, ey in enemies:
                d = abs(ex - (me[0] + mv[0])) + abs(ey - (me[1] + mv[1]))
                if d == 0:
                    sc -= 100
                elif d == 1:
                    sc -= 6
                elif d == 2:
                    sc -= 2

        if best_sc is None or sc > best_sc:
            best_sc = sc
            best_mv = mv

    dx = clamp_step(best_mv[0])
    dy = clamp_step(best_mv[1])
    return [dx, dy]

